  Q("math-8", { paper: "P1", marks: 6, diff: 2, q: "The graph of \\(f(x) = a\\sin(bx) + c\\), \\(0 \\le x \\le 2\\pi\\), is shown. It has a maximum at \\(\\left(\\frac{\\pi}{4}, 5\\right)\\) and a minimum at \\(\\left(\\frac{3\\pi}{4}, -1\\right)\\). Find \\(a\\), \\(b\\) and \\(c\\).", graph: { title: "y = a sin(bx) + c", x: [0, 6.6], y: [-2, 6], curves: [{ f: (x) => 3 * Math.sin(2 * x) + 2, domain: [0, 2 * Math.PI] }], points: [{ at: [Math.PI / 4, 5], label: "(π/4, 5)" }, { at: [(3 * Math.PI) / 4, -1], label: "(3π/4, −1)" }] }, ms: ["\\(a = \\frac{5 - (-1)}{2} = 3\\) [M1][A1]", "\\(c = \\frac{5 + (-1)}{2} = 2\\) [A1]", "period \\(= \\pi\\) [A1]", "\\(b = \\frac{2\\pi}{\\pi} = 2\\) [M1][A1]"] });
  Q("math-8", { paper: "P1", marks: 6, diff: 3, q: "Solve \\(2\\cos^2 x + 3\\sin x = 3\\) for \\(0 \\le x \\le 2\\pi\\).", ms: ["\\(2(1 - \\sin^2 x) + 3\\sin x - 3 = 0\\) [M1]", "\\(2\\sin^2 x - 3\\sin x + 1 = 0\\) [A1]", "\\((2\\sin x - 1)(\\sin x - 1) = 0\\) [M1]", "\\(\\sin x = \\frac{1}{2}\\): \\(x = \\frac{\\pi}{6}, \\frac{5\\pi}{6}\\) [A1][A1]", "\\(\\sin x = 1\\): \\(x = \\frac{\\pi}{2}\\) [A1]"] });
  Q("math-8", { paper: "P1", marks: 5, diff: 2, q: "Sketch \\(y = 2\\cos x - 1\\) for \\(0 \\le x \\le 2\\pi\\), labelling the maximum and minimum points and the \\(x\\)-intercepts.", model: { x: [0, 6.6], y: [-3.5, 2], curves: [{ f: (x) => 2 * Math.cos(x) - 1, domain: [0, 2 * Math.PI] }], points: [{ at: [0, 1], label: "(0, 1)" }, { at: [Math.PI, -3], label: "(π, −3)" }, { at: [2 * Math.PI, 1], label: "(2π, 1)" }, { at: [Math.PI / 3, 0], label: "π/3" }, { at: [(5 * Math.PI) / 3, 0], label: "5π/3" }] }, ms: ["cosine shape, one full cycle [A1]", "maxima \\((0, 1)\\) and \\((2\\pi, 1)\\) [A1]", "minimum \\((\\pi, -3)\\) [A1]", "intercepts \\(x = \\frac{\\pi}{3}, \\frac{5\\pi}{3}\\) [A1][A1]"] });
  Q("math-8", { paper: "P1", marks: 5, diff: 2, q: "Given \\(\\sin\\theta = \\frac{5}{13}\\) and \\(\\frac{\\pi}{2} < \\theta < \\pi\\), find the exact values of \\(\\cos\\theta\\), \\(\\sin 2\\theta\\) and \\(\\cos 2\\theta\\).", ms: ["\\(\\cos\\theta = -\\frac{12}{13}\\) (negative in Q2) [A1][R1]", "\\(\\sin 2\\theta = 2\\left(\\frac{5}{13}\\right)\\left(-\\frac{12}{13}\\right) = -\\frac{120}{169}\\) [M1][A1]", "\\(\\cos 2\\theta = 1 - 2\\left(\\frac{25}{169}\\right) = \\frac{119}{169}\\) [A1]"] });
  Q("math-8", { paper: "P2", marks: 6, diff: 2, q: "The depth of water in a harbour is \\(d(t) = 4\\cos(0.5t) + 7\\) metres, \\(t\\) hours after midnight.<br>(a) Find the maximum depth. [1]<br>(b) Find the period. [2]<br>(c) A boat needs at least 8 m of water. Find the first time interval after midnight when it can enter. [3]", graph: { title: "d(t)", x: [0, 14], y: [0, 12], xLabel: "t", yLabel: "d", curves: [{ f: (x) => 4 * Math.cos(0.5 * x) + 7, domain: [0, 13] }], hlines: [{ y: 8, label: "d = 8" }] }, ms: ["(a) 11 m [A1]", "(b) \\(\\frac{2\\pi}{0.5} = 4\\pi = 12.6\\) hours [M1][A1]", "(c) \\(4\\cos(0.5t) + 7 = 8\\) [M1]", "\\(0 \\le t \\le 2.64\\) [A1], then again from \\(t = 9.93\\) [A1]"] });
