  Q("math-8", { paper: "P1", marks: 4, diff: 3, q: "Show that \\(\\frac{\\sin 2x}{1 + \\cos 2x} = \\tan x\\).", ms: ["\\(\\sin 2x = 2\\sin x\\cos x\\) [A1]", "\\(1 + \\cos 2x = 2\\cos^2 x\\) [A1]", "\\(\\frac{2\\sin x\\cos x}{2\\cos^2 x}\\) [M1]", "\\(= \\frac{\\sin x}{\\cos x} = \\tan x\\) [AG]"] });

