  Q("math-9", { paper: "P2", marks: 6, diff: 2, q: "The cumulative frequency graph shows the times, in minutes, taken by 80 students to finish a puzzle.<br>(a) Find the median. [2]<br>(b) Find the interquartile range. [3]<br>(c) Find the number of students who took more than 30 minutes. [1]", graph: { title: "Cumulative frequency", x: [0, 50], y: [0, 85], xLabel: "time", yLabel: "cf", curves: [{ f: (x) => 80 / (1 + Math.exp(-(x - 22) / 5)), domain: [0, 48] }], hlines: [{ y: 40, label: "40" }, { y: 20, label: "20" }, { y: 60, label: "60" }] }, ms: ["(a) read across from 40: median \\(\\approx 22\\) min [M1][A1]", "(b) \\(Q_1 \\approx 16.5\\), \\(Q_3 \\approx 27.5\\) [A1][A1]", "IQR \\(\\approx 11\\) min [A1]", "(c) cf at 30 ≈ 67, so \\(80 - 67 = 13\\) students (accept 12-15) [A1]"], numeric: { value: 22, tol: 1 } });
  Q("math-9", { paper: "P2", marks: 6, diff: 2, q: "The data show the hours of revision, \\(x\\), and test score, \\(y\\), of 8 students.<div class='table-wrap'><table class='compare'><tr><th>x</th><td>2</td><td>4</td><td>5</td><td>6</td><td>8</td><td>9</td><td>11</td><td>12</td></tr><tr><th>y</th><td>45</td><td>52</td><td>55</td><td>61</td><td>67</td><td>70</td><td>78</td><td>83</td></tr></table></div>(a) Find Pearson's correlation coefficient \\(r\\). [2]<br>(b) Find the equation of the regression line of \\(y\\) on \\(x\\). [2]<br>(c) Estimate the score of a student who revised for 7 hours. [2]", ms: ["(a) \\(r = 0.998\\) [A2]", "(b) \\(y = 3.75x + 37.2\\) [A1][A1]", "(c) \\(3.75(7) + 37.2\\) [M1] \\(= 63.4\\) [A1]"], numeric: { value: 63.4, tol: 0.3 } });
  Q("math-9", { paper: "P2", marks: 5, diff: 2, q: "The box-and-whisker plot below summarises the masses (kg) of 60 parcels.<br>(a) Write down the median and the IQR. [2]<br>(b) Show that the maximum value is an outlier. [3]", graph: { title: "Box plot", x: [0, 30], y: [0, 4], grid: false, origin: false, xLabel: "kg", yLabel: " ", lines: [{ from: [3, 2], to: [8, 2], color: "muted" }, { from: [8, 1], to: [8, 3] }, { from: [8, 3], to: [14, 3] }, { from: [8, 1], to: [14, 1] }, { from: [11, 1], to: [11, 3] }, { from: [14, 1], to: [14, 3] }, { from: [14, 2], to: [28, 2], color: "muted" }], points: [{ at: [3, 2], label: "3" }, { at: [8, 3], label: "8" }, { at: [11, 3], label: "11" }, { at: [14, 3], label: "14" }, { at: [28, 2], label: "28" }] }, ms: ["(a) median 11 [A1], IQR \\(= 14 - 8 = 6\\) [A1]", "(b) \\(Q_3 + 1.5 \\times IQR = 14 + 9\\) [M1] \\(= 23\\) [A1]", "\\(28 > 23\\), so it is an outlier [R1]"] });
  Q("math-9", { paper: "P2", marks: 4, diff: 2, numeric: { value: 10, tol: 0.001 }, q: "A frequency table is given.<div class='table-wrap'><table class='compare'><tr><th>Score</th><td>10</td><td>12</td><td>14</td><td>16</td><td>18</td></tr><tr><th>Frequency</th><td>3</td><td>7</td><td>9</td><td>k</td><td>4</td></tr></table></div>The mean is \\(\\frac{472}{33}\\). Find \\(k\\), and write down the standard deviation.", ms: ["\\(\\frac{312 + 16k}{23 + k} = \\frac{472}{33}\\) [M1]", "\\(33(312 + 16k) = 472(23 + k)\\) [A1]", "\\(56k = 560\\), \\(k = 10\\) [A1]", "standard deviation \\(= 2.32\\) [A1]"] });
  Q("math-9", { paper: "P2", marks: 3, diff: 1, q: "Each value in a data set is multiplied by 3 and then 5 is added. The original mean is 12 and the original standard deviation is 2.5. Find the new mean and standard deviation.", ms: ["new mean \\(= 3(12) + 5 = 41\\) [M1][A1]", "new SD \\(= 3(2.5) = 7.5\\) [A1]"] });
  Q("math-9", { paper: "P2", marks: 4, diff: 2, q: "The scatter diagram shows the regression line of \\(y\\) on \\(x\\), \\(y = 2.4x + 6\\), fitted to data with \\(2 \\le x \\le 10\\).<br>(a) Estimate \\(y\\) when \\(x = 7\\). [2]<br>(b) Explain why the line should not be used to estimate \\(y\\) when \\(x = 25\\). [1]<br>(c) Explain why it should not be used to estimate \\(x\\) given \\(y\\). [1]", graph: { title: "Scatter and regression line", x: [0, 12], y: [0, 35], points: [[2, 11], [3, 13], [4, 15], [5, 19], [6, 20], [7, 22], [8, 26], [9, 27], [10, 31]].map((p) => ({ at: p })), lines: [{ from: [1, 8.4], to: [11, 32.4], color: "b", label: "y = 2.4x + 6" }] }, ms: ["(a) \\(2.4(7) + 6 = 22.8\\) [M1][A1]", "(b) extrapolation - 25 is outside the data range [R1]", "(c) the line is \\(y\\) on \\(x\\); predicting \\(x\\) needs the \\(x\\) on \\(y\\) line [R1]"], numeric: { value: 22.8, tol: 0.05 } });
  Q("math-9", { paper: "P2", marks: 4, diff: 2, q: "The histogram shows the heights of seedlings in a sample. (Class width 2 cm.)<br>(a) Write down the modal class. [1]<br>(b) Find the total number of seedlings. [1]<br>(c) Estimate the mean height. [2]", graph: { title: "Histogram", x: [0, 12], y: [0, 14], xLabel: "cm", yLabel: "f", areas: [[0, 4], [2, 9], [4, 13], [6, 8], [8, 6]].map(([a, f]) => ({ pts: [[a, 0], [a + 2, 0], [a + 2, f], [a, f]], color: "a", label: String(f), at: [a + 0.7, f + 0.4] })) }, ms: ["(a) \\(4 \\le h < 6\\) [A1]", "(b) \\(4 + 9 + 13 + 8 + 6 = 40\\) [A1]", "(c) \\(\\frac{1(4) + 3(9) + 5(13) + 7(8) + 9(6)}{40}\\) [M1] \\(= 5.15\\) cm [A1]"], numeric: { value: 5.15, tol: 0.01 } });

