  Q("math-11", { paper: "P2", marks: 6, diff: 2, q: "The probability distribution of \\(X\\) is:<div class='table-wrap'><table class='compare'><tr><th>x</th><td>0</td><td>1</td><td>2</td><td>3</td></tr><tr><th>P(X = x)</th><td>0.1</td><td>k</td><td>0.3</td><td>2k</td></tr></table></div>(a) Find \\(k\\). [2]<br>(b) Find \\(E(X)\\). [2]<br>(c) A game costs $2 to play and pays $\\(X\\). Is the game fair? [2]", ms: ["(a) \\(0.4 + 3k = 1\\) [M1] \\(k = 0.2\\) [A1]", "(b) \\(0 + 0.2 + 0.6 + 1.2 = 2\\) [M1][A1]", "(c) expected gain \\(= 2 - 2 = 0\\) [M1], so the game is fair [A1]"], numeric: { value: 0.2, tol: 0.001 } });
  Q("math-11", { paper: "P2", marks: 6, diff: 2, q: "\\(X \\sim B(12, 0.35)\\). Find:<br>(a) \\(P(X = 4)\\) [2]<br>(b) \\(P(X \\le 3)\\) [2]<br>(c) \\(P(X > 5)\\) [2]", ms: ["(a) binompdf: 0.237 [M1][A1]", "(b) binomcdf: 0.347 [M1][A1]", "(c) \\(1 - P(X \\le 5) = 1 - 0.787 = 0.213\\) [M1][A1]"], numeric: { value: 0.237, tol: 0.002 } });
