  Q("math-11", { paper: "P2", marks: 3, diff: 2, q: "A multiple-choice test has 20 questions each with 4 options. A student guesses every answer. Find the expected number correct and the probability of getting at least 8 correct.", ms: ["\\(X \\sim B(20, 0.25)\\) [M1]", "\\(E(X) = 5\\) [A1]", "\\(P(X \\ge 8) = 1 - P(X \\le 7) = 0.102\\) [A1]"], numeric: { value: 0.102, tol: 0.002 } });
  Q("math-11", { paper: "P1", marks: 4, diff: 2, q: "The diagram shows the normal curve of \\(X \\sim N(50, \\sigma^2)\\). \\(P(X > 58) = 0.2\\). Using the symmetry of the curve, find:<br>(a) \\(P(X < 42)\\) [1]<br>(b) \\(P(42 < X < 58)\\) [1]<br>(c) \\(P(50 < X < 58)\\) [2]", graph: { title: "X ~ N(50, σ²)", x: [25, 75], y: [0, 0.06], grid: false, yLabel: " ", curves: [{ f: (x) => Math.exp(-sq(x - 50) / 200) / (10 * Math.sqrt(2 * Math.PI)) }], vlines: [{ x: 42, label: "42" }, { x: 50, label: "50" }, { x: 58, label: "58" }] }, ms: ["(a) 0.2 by symmetry [A1]", "(b) \\(1 - 0.4 = 0.6\\) [A1]", "(c) \\(\\frac{0.6}{2} = 0.3\\) [M1][A1]"], numeric: { value: 0.3, tol: 0.001 } });

