  Q("math-12", { paper: "P1", marks: 7, diff: 2, q: "Let \\(f(x) = x^3 - 3x^2 - 9x + 5\\).<br>(a) Find \\(f'(x)\\). [2]<br>(b) Find the coordinates of the stationary points and determine their nature. [5]", model: { x: [-4, 6], y: [-25, 15], curves: [{ f: (x) => x ** 3 - 3 * x * x - 9 * x + 5, domain: [-3, 5.2] }], points: [{ at: [-1, 10], label: "(−1, 10) max" }, { at: [3, -22], label: "(3, −22) min" }] }, ms: ["(a) \\(3x^2 - 6x - 9\\) [A2]", "(b) \\(3(x - 3)(x + 1) = 0\\) [M1]", "\\((-1, 10)\\) [A1] and \\((3, -22)\\) [A1]", "\\(f''(x) = 6x - 6\\): \\(f''(-1) < 0\\) max, \\(f''(3) > 0\\) min [R1][A1]"] });
  Q("math-12", { paper: "P1", marks: 4, diff: 2, q: "The graph of \\(y = f(x)\\) is shown. It has stationary points at \\(x = -2\\) and \\(x = 1\\). Sketch the graph of \\(y = f'(x)\\).", graph: { title: "y = f(x)", x: [-4, 3], y: [-6, 8], curves: [{ f: (x) => 2 * x ** 3 / 3 + x * x - 4 * x, domain: [-3.8, 2.6] }], points: [{ at: [-2, 2 * -8 / 3 + 4 + 8], label: "x = −2" }, { at: [1, 2 / 3 + 1 - 4], label: "x = 1" }] }, model: { x: [-4, 3], y: [-6, 8], curves: [{ f: (x) => 2 * x * x + 2 * x - 4, domain: [-3.4, 2.2] }], points: [{ at: [-2, 0], label: "(−2, 0)" }, { at: [1, 0], label: "(1, 0)" }] }, ms: ["\\(f'\\) is a quadratic (parabola) [A1]", "\\(x\\)-intercepts at \\(-2\\) and \\(1\\) [A1]", "\\(f' > 0\\) for \\(x < -2\\) and \\(x > 1\\), \\(f' < 0\\) between [A1]", "minimum of \\(f'\\) at \\(x = -0.5\\) (point of inflexion of \\(f\\)) [A1]"] });
  Q("math-12", { paper: "P1", marks: 5, diff: 2, q: "Find the equation of the normal to the curve \\(y = x^2 - 4x + 1\\) at the point where \\(x = 3\\).", ms: ["\\(\\frac{dy}{dx} = 2x - 4\\) [A1]", "at \\(x = 3\\): gradient 2, \\(y = -2\\) [A1]", "normal gradient \\(-\\frac{1}{2}\\) [M1]", "\\(y + 2 = -\\frac{1}{2}(x - 3)\\) [M1][A1]"] });
  Q("math-12", { paper: "P1", marks: 4, diff: 2, q: "Differentiate:<br>(a) \\(y = x^2e^{3x}\\) [2]<br>(b) \\(y = \\frac{\\ln x}{x}\\) [2]", ms: ["(a) product rule: \\(2xe^{3x} + 3x^2e^{3x}\\) [M1][A1]", "(b) quotient rule: \\(\\frac{x \\cdot \\frac{1}{x} - \\ln x}{x^2} = \\frac{1 - \\ln x}{x^2}\\) [M1][A1]"] });
  Q("math-12", { paper: "P1", marks: 4, diff: 2, q: "Find \\(\\frac{dy}{dx}\\) for \\(y = \\sin^3(2x)\\).", ms: ["chain rule [M1]", "\\(3\\sin^2(2x) \\times \\cos(2x) \\times 2\\) [A1][A1]", "\\(= 6\\sin^2(2x)\\cos(2x)\\) [A1]"] });
  Q("math-12", { paper: "P1", marks: 5, diff: 3, q: "The curve \\(y = ax^2 + bx\\) has a tangent \\(y = 3x - 4\\) at the point where \\(x = 2\\). Find \\(a\\) and \\(b\\).", ms: ["at \\(x = 2\\): \\(y = 2\\) [A1]", "\\(4a + 2b = 2\\) [A1]", "\\(\\frac{dy}{dx} = 2ax + b\\), \\(4a + b = 3\\) [M1][A1]", "\\(a = 1\\), \\(b = -1\\) [A1]"] });
  Q("math-12", { paper: "P1", marks: 4, diff: 2, q: "The graph of \\(y = f'(x)\\) is shown. Write down:<br>(a) the \\(x\\)-coordinate of the local maximum of \\(f\\) [2]<br>(b) the interval where \\(f\\) is concave up [2]", graph: { title: "y = f′(x)", x: [-3, 5], y: [-5, 6], yLabel: "f′", curves: [{ f: (x) => (x + 1) * (x - 3), domain: [-2.6, 4.6] }], points: [{ at: [-1, 0], label: "−1" }, { at: [3, 0], label: "3" }] }, ms: ["(a) \\(f'\\) changes from + to − at \\(x = -1\\) [R1] so max at \\(x = -1\\) [A1]", "(b) \\(f'' > 0\\) where \\(f'\\) is increasing [R1]: \\(x > 1\\) [A1]"] });
  Q("math-12", { paper: "P2", marks: 6, diff: 3, q: "An open box is made from a 30 cm by 20 cm sheet by cutting squares of side \\(x\\) cm from each corner.<br>(a) Show that the volume is \\(V = x(30 - 2x)(20 - 2x)\\). [1]<br>(b) Find the value of \\(x\\) that maximises \\(V\\). [3]<br>(c) Find the maximum volume. [2]", ms: ["(a) base \\((30 - 2x)\\) by \\((20 - 2x)\\), height \\(x\\) [AG]", "(b) \\(V'(x) = 12x^2 - 200x + 600 = 0\\) [M1][A1]", "\\(x = 3.92\\) (reject 12.7, outside \\(0 < x < 10\\)) [A1]", "(c) \\(V = 1056\\) cm³ [A2]"], numeric: { value: 1056, tol: 1 } });

