  Q("math-13", { paper: "P1", marks: 6, diff: 2, q: "The diagram shows part of the graph of \\(y = 6x - x^2\\). Find the area of the shaded region enclosed by the curve and the \\(x\\)-axis.", graph: { title: "y = 6x − x²", x: [-1, 7], y: [-2, 10], curves: [{ f: (x) => 6 * x - x * x, domain: [-0.5, 6.5] }], areas: [{ pts: Array.from({ length: 31 }, (_, i) => [i * 0.2, 6 * i * 0.2 - sq(i * 0.2)]), color: "a" }] }, ms: ["limits 0 and 6 [A1]", "\\(\\int_0^6 (6x - x^2)\\,dx\\) [M1]", "\\(\\left[3x^2 - \\frac{x^3}{3}\\right]_0^6\\) [A1][A1]", "\\(108 - 72 = 36\\) [M1][A1]"], numeric: { value: 36, tol: 0.001 } });
  Q("math-13", { paper: "P2", marks: 5, diff: 2, q: "Find the area enclosed between \\(y = x^2\\) and \\(y = x + 2\\).", graph: { title: "y = x² and y = x + 2", x: [-3, 4], y: [-1, 7], curves: [{ f: (x) => x * x, label: "y = x²" }, { f: (x) => x + 2, color: "b", label: "y = x + 2", labelX: 2.6 }] }, ms: ["intersections \\(x = -1, 2\\) [A1]", "\\(\\int_{-1}^{2} (x + 2 - x^2)\\,dx\\) [M1][A1]", "\\(= 4.5\\) [A2]"], numeric: { value: 4.5, tol: 0.01 } });
  Q("math-13", { paper: "P1", marks: 4, diff: 2, q: "Given \\(f'(x) = 6x^2 - 4x\\) and \\(f(1) = 5\\), find \\(f(x)\\).", ms: ["\\(f(x) = 2x^3 - 2x^2 + c\\) [A1][A1]", "\\(5 = 2 - 2 + c\\) [M1]", "\\(f(x) = 2x^3 - 2x^2 + 5\\) [A1]"] });
  Q("math-13", { paper: "P1", marks: 5, diff: 3, q: "Find \\(\\int x e^{x^2}\\,dx\\) and hence evaluate \\(\\int_0^1 x e^{x^2}\\,dx\\) exactly.", ms: ["substitution \\(u = x^2\\), \\(du = 2x\\,dx\\) [M1]", "\\(\\frac{1}{2}e^{x^2} + c\\) [A1][A1]", "\\(\\frac{1}{2}(e - 1)\\) [M1][A1]"] });
  Q("math-13", { paper: "P1", marks: 4, diff: 2, q: "Given \\(\\int_1^4 f(x)\\,dx = 7\\), find:<br>(a) \\(\\int_1^4 3f(x)\\,dx\\) [1]<br>(b) \\(\\int_1^4 (f(x) + 2)\\,dx\\) [2]<br>(c) \\(\\int_4^1 f(x)\\,dx\\) [1]", ms: ["(a) 21 [A1]", "(b) \\(7 + 2(3) = 13\\) [M1][A1]", "(c) \\(-7\\) [A1]"] });
