  // ===================== 14 Kinematics =====================
  Q("math-14", { paper: "P2", marks: 7, diff: 2, q: "The velocity–time graph of a particle is shown for \\(0 \\le t \\le 6\\), where \\(v(t) = t^2 - 6t + 5\\) m s⁻¹.<br>(a) Find the times when the particle is at rest. [2]<br>(b) Find the acceleration when \\(t = 4\\). [2]<br>(c) Find the total distance travelled. [3]", graph: { title: "v(t) = t² − 6t + 5", x: [0, 6.5], y: [-5, 6], xLabel: "t", yLabel: "v", curves: [{ f: (t) => t * t - 6 * t + 5, domain: [0, 6] }] }, ms: ["(a) \\((t - 1)(t - 5) = 0\\): \\(t = 1, 5\\) [M1][A1]", "(b) \\(a = 2t - 6 = 2\\) m s⁻² [M1][A1]", "(c) \\(\\int_0^6 |v|\\,dt\\) [M1]", "\\(= 2.33 + 10.67 + 2.33 = 15.3\\) m [A2]"], numeric: { value: 15.3, tol: 0.1 } });
